<?php declare(strict_types=1); namespace App\Web\Admin\Role\Create;
use App\Role\RoleRepository; use Psr\Http\Message\{ResponseFactoryInterface,ResponseInterface,ServerRequestInterface}; use Yiisoft\Router\UrlGeneratorInterface; use Yiisoft\Yii\View\Renderer\WebViewRenderer;
final readonly class Action{public function __construct(private WebViewRenderer $view,private RoleRepository $roles,private ResponseFactoryInterface $factory,private UrlGeneratorInterface $url){} public function __invoke(ServerRequestInterface $r):ResponseInterface{$p=$r->getParsedBody()??[]; if($r->getMethod()==='POST'){$this->roles->create((string)$p['title']); return $this->factory->createResponse(302)->withHeader('Location',$this->url->generate('admin/role/index'));} return $this->view->render(__DIR__.'/template');}}
